"""gw_client.py  --  talks to an AgentCore Gateway (or to the offline 'practice gateway').   >>> YOU DO NOT EDIT THIS FILE <<<

Same file as Day 11 Lab 15, plus two Day 12 additions:
  - the practice gateway can have a PRACTICE POLICY ENGINE in front of the tools (policy_engine.py)
  - is_denied() recognises a reply that says "a policy blocked this"

A Gateway speaks MCP. MCP over the web is just JSON messages (JSON-RPC) sent with POST:
    {"jsonrpc":"2.0","id":1,"method":"tools/list"}                                       "what tools do you have?"
    {"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":...,"arguments":{}}}  "run this tool"
Because the Gateway uses IAM for 'who may call me', every request is SIGNED with your AWS keys (called SigV4).
boto3 does the signing for you, exactly as it does for Bedrock.
"""
import csv
import json
import re
import time
import urllib.error
import urllib.request
from pathlib import Path

import rag_tool
import tools_core

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
PREFIX = "askit-lambda___"          # the Gateway names a tool  <target name>___<tool name>
SAVE = HERE / "my_gateway.json"     # your own Gateway address and ARN (never pushed to GitHub)
DAY11_SAVE = ROOT / "Day11" / "Labs" / "lab15-askit-gateway" / "my_gateway.json"   # the address you saved yesterday


def _data():
    def rows(name):
        with open(ROOT / "askit_data" / name, encoding="utf-8") as f:
            return list(csv.DictReader(f))
    return {"tickets": rows("tickets.csv"), "users": rows("users.csv"), "kb": rag_tool.load_kb_dir(ROOT / "askit_data" / "kb")}


def load_saved():
    """-> {"url": ..., "arn": ...}. Falls back to the address you saved in Lab 15 yesterday."""
    for p in (SAVE, DAY11_SAVE):
        try:
            d = json.loads(p.read_text(encoding="utf-8"))
            if d.get("url"):
                return {"url": d.get("url", ""), "arn": d.get("arn", "")}
        except Exception:
            continue
    return {"url": "", "arn": ""}


def save(url, arn=""):
    SAVE.write_text(json.dumps({"url": url.strip(), "arn": arn.strip()}), encoding="utf-8")


def region_of(url):
    m = re.search(r"\.bedrock-agentcore\.([a-z0-9-]+)\.amazonaws\.com", url or "")
    return m.group(1) if m else "us-east-1"


class Result:
    def __init__(self, ok, data=None, error="", ms=0, request=None, response=None, status=None, policy=None):
        self.ok, self.data, self.error, self.ms, self.request, self.response, self.status, self.policy = ok, data, error, ms, request, response, status, policy


class PracticeGateway:
    """Works with NO AWS. It answers like a real Gateway would, using the same tool code.
    engine: an optional policy_engine.Engine. strict: use the hardened tools (exact ids only)."""

    def __init__(self, engine=None, strict=False):
        self.engine, self.strict = engine, strict
        self.funcs = tools_core.make(_data(), strict=strict)
        self.label = "Practice gateway (offline)" + (f" · policy engine {engine.mode}" if engine else "") + (" · strict tools" if strict else "")

    def rpc(self, method, params=None):
        t0 = time.time()
        req = {"jsonrpc": "2.0", "id": 1, "method": method, **({"params": params} if params else {})}
        policy = None
        if method == "tools/list":
            tools = [{"name": PREFIX + n, "description": d, "inputSchema": {"type": "object", "properties": {}}} for n, d in tools_core.TOOLS.items()]
            schema = json.loads((HERE / "tool_schema.json").read_text(encoding="utf-8"))
            for t in tools:
                t["inputSchema"] = next(s["inputSchema"] for s in schema if PREFIX + s["name"] == t["name"])
            resp = {"jsonrpc": "2.0", "id": 1, "result": {"tools": tools}}
        elif method == "tools/call":
            short = params["name"].replace(PREFIX, "")
            args = params.get("arguments", {})
            if self.engine:                                       # the policy engine looks at EVERY call before the tool does
                policy = self.engine.decide(short, args)
                if policy["blocked"]:
                    msg = "Denied by policy. " + policy["why"]
                    resp = {"jsonrpc": "2.0", "id": 1, "error": {"code": -32003, "message": msg}}
                    time.sleep(0.1)
                    return Result(False, resp, msg, int((time.time() - t0) * 1000), req, resp, 403, policy)
            fn = self.funcs.get(short)
            if fn is None:
                resp = {"jsonrpc": "2.0", "id": 1, "error": {"code": -32602, "message": f"Unknown tool: {params['name']}"}}
            else:
                try:
                    out = fn(**args)
                    resp = {"jsonrpc": "2.0", "id": 1, "result": {"content": [{"type": "text", "text": json.dumps(out)}], "isError": "error" in out}}
                except TypeError as e:
                    resp = {"jsonrpc": "2.0", "id": 1, "error": {"code": -32602, "message": f"Bad inputs: {e}"}}
        else:
            resp = {"jsonrpc": "2.0", "id": 1, "error": {"code": -32601, "message": "Method not found"}}
        time.sleep(0.15)
        return Result("error" not in resp, resp, resp.get("error", {}).get("message", ""), int((time.time() - t0) * 1000), req, resp, 200, policy)


class AwsGateway:
    label = "My Gateway (AWS)"

    def __init__(self, url):
        self.url = url.strip()
        self.region = region_of(self.url)

    def rpc(self, method, params=None):
        import boto3
        from botocore.auth import SigV4Auth
        from botocore.awsrequest import AWSRequest
        req = {"jsonrpc": "2.0", "id": 1, "method": method, **({"params": params} if params else {})}
        body = json.dumps(req)
        creds = boto3.Session().get_credentials()
        if creds is None:
            return Result(False, error="No AWS keys found. Check the .env file in the course folder (AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY).", request=req)
        aws = AWSRequest(method="POST", url=self.url, data=body, headers={"Content-Type": "application/json", "Accept": "application/json"})
        SigV4Auth(creds.get_frozen_credentials(), "bedrock-agentcore", self.region).add_auth(aws)
        r = urllib.request.Request(self.url, data=body.encode("utf-8"), headers=dict(aws.headers.items()), method="POST")
        t0 = time.time()
        try:
            with urllib.request.urlopen(r, timeout=30) as resp:
                text, status = resp.read().decode("utf-8"), resp.status
        except urllib.error.HTTPError as e:
            text, status = e.read().decode("utf-8", "replace"), e.code
        except Exception as e:                                       # noqa: BLE001
            return Result(False, error=f"Could not reach the address: {type(e).__name__}: {e}", request=req, ms=int((time.time() - t0) * 1000))
        ms = int((time.time() - t0) * 1000)
        try:
            data = json.loads(text)
        except Exception:
            return Result(False, error=f"HTTP {status}: {text[:300]}", request=req, response=text, ms=ms, status=status)
        if status >= 400 or "error" in data:
            msg = (data.get("error") or {}).get("message") if isinstance(data.get("error"), dict) else data.get("message") or text[:300]
            return Result(False, data, error=explain(status, msg), request=req, response=data, ms=ms, status=status)
        return Result(True, data, request=req, response=data, ms=ms, status=status)


def explain(status, msg):
    """Plain-English hint for the errors people meet most."""
    hint = {403: "Either a POLICY blocked this call (read the message above) or your AWS user is not allowed to call this Gateway. Tell the trainer if there is no word 'policy' in it.",
            401: "The Gateway did not accept your sign-in. Check the Gateway was created with 'IAM' as the inbound auth, and your keys are in .env.",
            404: "Nothing lives at this address. Copy the Gateway URL again from the console (it ends with /mcp).",
            429: "Too many requests. Wait ten seconds and try again."}.get(status, "")
    return f"HTTP {status}: {msg}. {hint}".strip()


def make_gateway(mode, url="", engine=None, strict=False):
    return PracticeGateway(engine, strict) if mode == "practice" else AwsGateway(url)


def tools_of(result):
    return result.data["result"]["tools"] if result.ok else []


def is_denied(result):
    """True when the reply says a policy (or permission rule) refused the call. The real Gateway words this differently from the
    practice one, so we look for the usual words."""
    if result.ok:
        try:
            txt = result.data["result"]["content"][0]["text"].lower()
            return bool(result.data["result"].get("isError")) and any(w in txt for w in ("policy", "denied", "not authorized", "forbidden"))
        except Exception:
            return False
    low = (result.error or "").lower()
    return result.status == 403 or any(w in low for w in ("policy", "denied", "not authorized", "forbidden", "accessdenied"))


def call_text(result):
    """The tool's answer as a Python value (the Lambda's JSON arrives as text inside the MCP reply)."""
    if not result.ok:
        return {"error": result.error}
    try:
        txt = result.data["result"]["content"][0]["text"]
    except Exception:
        return {"error": "Unexpected reply shape."}
    try:
        return json.loads(txt)
    except Exception:
        return {"text": txt}
